import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';

import '../widgets/app_colors.dart';

class LocationPickerPage extends StatefulWidget {
  const LocationPickerPage({super.key});

  @override
  State<LocationPickerPage> createState() => _LocationPickerPageState();
}

class _LocationPickerPageState extends State<LocationPickerPage> {
  final TextEditingController _searchController = TextEditingController();
  String _query = '';
  String? _selectedProvinceCode;
  String? _selectedDistrictCode;
  bool _loading = true;
  String? _loadError;
  bool _resolvingMerge = false;

  List<_LocationNode> _currentList = [];
  final List<_LocationNode> _provinceList = [];
  final Map<String, _LocationNode> _provinceByCode = {};
  final Map<String, _LocationNode> _districtByCode = {};
  final Map<String, List<_LocationNode>> _districtCache = {};
  final Map<String, List<_LocationNode>> _wardCache = {};
  final Map<String, List<_LocationNode>> _openApiDistrictCache = {};
  final Map<String, List<_LocationNode>> _openApiWardCache = {};
  final Map<String, List<_OpenDistrictRef>> _openApiDistrictIndex = {};
  List<_LocationNode>? _openApiProvinceList;

  static const Map<String, String> _provinceOverrideByWardCode = {
    '31078': 'Tinh An Giang',
  };

  static const String _apiBaseUrl = 'https://tinhthanhpho.com/api/v1';
  static const String _openApiBaseUrl = 'https://provinces.open-api.vn/api';
  static const String _mergeApiKey = String.fromEnvironment('TTP_API_KEY');
  static const String _trackAsiaApiKey =
      String.fromEnvironment('TRACKASIA_API_KEY');
  static const String _trackAsiaBaseUrl = 'https://maps.track-asia.com/api/v2';

  static String _normalize(String value) {
    var normalized = value.toLowerCase();
    normalized = normalized
        .replaceAll(
          RegExp(r'[\u00e0\u00e1\u1ea3\u00e3\u1ea1\u00e2\u1ea7\u1ea5\u1ea9\u1eab\u1ead\u0103\u1eb1\u1eaf\u1eb3\u1eb5\u1eb7]'),
          'a',
        )
        .replaceAll(
          RegExp(r'[\u00e8\u00e9\u1ebb\u1ebd\u1eb9\u00ea\u1ec1\u1ebf\u1ec3\u1ec5\u1ec7]'),
          'e',
        )
        .replaceAll(
          RegExp(r'[\u00ec\u00ed\u1ec9\u0129\u1ecb]'),
          'i',
        )
        .replaceAll(
          RegExp(r'[\u00f2\u00f3\u1ecf\u00f5\u1ecd\u00f4\u1ed3\u1ed1\u1ed5\u1ed7\u1ed9\u01a1\u1edd\u1edb\u1edf\u1ee1\u1ee3]'),
          'o',
        )
        .replaceAll(
          RegExp(r'[\u00f9\u00fa\u1ee7\u0169\u1ee5\u01b0\u1eeb\u1ee9\u1eed\u1eef\u1ef1]'),
          'u',
        )
        .replaceAll(
          RegExp(r'[\u1ef3\u00fd\u1ef7\u1ef9\u1ef5]'),
          'y',
        )
        .replaceAll(RegExp(r'[\u0111]'), 'd');
    return normalized;
  }

  static String _firstNonEmpty(List<String?> values) {
    for (final value in values) {
      if (value != null && value.trim().isNotEmpty) {
        return value.trim();
      }
    }
    return '';
  }

  static String _joinNonEmpty(List<String?> values) {
    final parts = <String>[];
    for (final value in values) {
      if (value != null && value.trim().isNotEmpty) {
        parts.add(value.trim());
      }
    }
    return parts.join(', ');
  }

  @override
  void initState() {
    super.initState();
    _loadProvinces();
  }

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<List<dynamic>> _fetchData(String path) async {
    final client = HttpClient();
    try {
      final uri = Uri.parse('$_apiBaseUrl$path');
      final request = await client.getUrl(uri);
      request.headers.set('Accept', 'application/json');
      final response = await request.close();
      final body = await response.transform(utf8.decoder).join();
      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw Exception('Request failed.');
      }
      final json = jsonDecode(body) as Map<String, dynamic>;
      final data = json['data'];
      if (data is List) return data;
      return [];
    } finally {
      client.close(force: true);
    }
  }

  Future<dynamic> _fetchOpenApi(String path) async {
    final client = HttpClient();
    try {
      final uri = Uri.parse('$_openApiBaseUrl$path');
      final request = await client.getUrl(uri);
      request.headers.set('Accept', 'application/json');
      final response = await request.close();
      final body = await response.transform(utf8.decoder).join();
      if (response.statusCode < 200 || response.statusCode >= 300) {
        return null;
      }
      if (body.isEmpty) return null;
      return jsonDecode(body);
    } finally {
      client.close(force: true);
    }
  }

  Future<List<_LocationNode>> _ensureOpenApiProvinces() async {
    final cached = _openApiProvinceList;
    if (cached != null) return cached;
    final data = await _fetchOpenApi('/?depth=1');
    if (data is! List) return [];
    final provinces = data
        .map((item) => _nodeFromApi(item as Map<String, dynamic>))
        .where((node) => node.code.isNotEmpty)
        .toList();
    provinces.sort((a, b) => a.name.compareTo(b.name));
    _openApiProvinceList = provinces;
    return provinces;
  }

  Future<List<_LocationNode>> _ensureOpenApiDistricts(
    String provinceCode,
  ) async {
    final cached = _openApiDistrictCache[provinceCode];
    if (cached != null) return cached;
    final data = await _fetchOpenApi('/p/$provinceCode?depth=2');
    if (data is! Map<String, dynamic>) return [];
    final districts = data['districts'];
    if (districts is! List) return [];
    final list = districts
        .map((item) => _nodeFromApi(item as Map<String, dynamic>))
        .where((node) => node.code.isNotEmpty)
        .toList();
    _openApiDistrictCache[provinceCode] = list;
    return list;
  }

  Future<List<_LocationNode>> _ensureOpenApiWards(
    String districtCode,
  ) async {
    final cached = _openApiWardCache[districtCode];
    if (cached != null) return cached;
    final data = await _fetchOpenApi('/d/$districtCode?depth=2');
    if (data is! Map<String, dynamic>) return [];
    final wards = data['wards'];
    if (wards is! List) return [];
    final list = wards
        .map((item) => _nodeFromApi(item as Map<String, dynamic>))
        .where((node) => node.code.isNotEmpty)
        .toList();
    _openApiWardCache[districtCode] = list;
    return list;
  }

  Future<void> _ensureOpenApiDistrictIndex() async {
    if (_openApiDistrictIndex.isNotEmpty) return;
    final data = await _fetchOpenApi('/?depth=2');
    if (data is! List) return;
    for (final province in data) {
      if (province is! Map<String, dynamic>) continue;
      final provinceName = province['name']?.toString() ?? '';
      final provinceCode = province['code']?.toString() ?? '';
      final districts = province['districts'];
      if (districts is! List) continue;
      for (final district in districts) {
        if (district is! Map<String, dynamic>) continue;
        final districtName = district['name']?.toString() ?? '';
        final districtCode = district['code']?.toString() ?? '';
        if (districtName.isEmpty || districtCode.isEmpty) continue;
        final key = _normalizeForMatch(districtName);
        final list = _openApiDistrictIndex.putIfAbsent(key, () => []);
        list.add(_OpenDistrictRef(
          code: districtCode,
          name: districtName,
          provinceCode: provinceCode,
          provinceName: provinceName,
        ));
      }
    }
  }

  Future<String?> _resolveOpenApiDisplay({
    required String wardName,
    required String districtName,
    required String provinceName,
  }) async {
    final normalizedProvince = _normalizeForMatch(provinceName);
    final normalizedDistrict = _normalizeForMatch(districtName);
    final normalizedWard = _normalizeForMatch(wardName);
    final provinces = await _ensureOpenApiProvinces();
    final matchedProvince = provinces.firstWhere(
      (node) => _normalizeForMatch(node.name) == normalizedProvince,
      orElse: () => const _LocationNode(code: '', name: ''),
    );
    if (matchedProvince.code.isNotEmpty) {
      final districts = await _ensureOpenApiDistricts(matchedProvince.code);
      final matchedDistrict = districts.firstWhere(
        (node) => _normalizeForMatch(node.name) == normalizedDistrict,
        orElse: () => const _LocationNode(code: '', name: ''),
      );
      if (matchedDistrict.code.isNotEmpty) {
        final wards = await _ensureOpenApiWards(matchedDistrict.code);
        final matchedWard = wards.firstWhere(
          (node) => _normalizeForMatch(node.name) == normalizedWard,
          orElse: () => const _LocationNode(code: '', name: ''),
        );
        if (matchedWard.code.isNotEmpty) {
          return '${matchedWard.name}, ${matchedDistrict.name}, '
              '${matchedProvince.name}';
        }
      }
    }
    await _ensureOpenApiDistrictIndex();
    final districtRefs = _openApiDistrictIndex[normalizedDistrict];
    if (districtRefs == null || districtRefs.isEmpty) return null;
    for (final districtRef in districtRefs) {
      final wards = await _ensureOpenApiWards(districtRef.code);
      final matchedWard = wards.firstWhere(
        (node) => _normalizeForMatch(node.name) == normalizedWard,
        orElse: () => const _LocationNode(code: '', name: ''),
      );
      if (matchedWard.code.isEmpty) continue;
      return '${matchedWard.name}, ${districtRef.name}, '
          '${districtRef.provinceName}';
    }
    return null;
  }

  Future<LocationSelection?> _resolveOpenApiSelectionByNames({
    required String wardName,
    required String districtName,
    required String provinceName,
  }) async {
    if (wardName.isEmpty || districtName.isEmpty || provinceName.isEmpty) {
      return null;
    }
    final normalizedProvince = _normalizeForMatch(provinceName);
    final normalizedDistrict = _normalizeForMatch(districtName);
    final normalizedWard = _normalizeForMatch(wardName);
    final provinces = await _ensureOpenApiProvinces();
    final matchedProvince = provinces.firstWhere(
      (node) => _normalizeForMatch(node.name) == normalizedProvince,
      orElse: () => const _LocationNode(code: '', name: ''),
    );
    if (matchedProvince.code.isNotEmpty) {
      final districts = await _ensureOpenApiDistricts(matchedProvince.code);
      final matchedDistrict = districts.firstWhere(
        (node) => _normalizeForMatch(node.name) == normalizedDistrict,
        orElse: () => const _LocationNode(code: '', name: ''),
      );
      if (matchedDistrict.code.isNotEmpty) {
        final wards = await _ensureOpenApiWards(matchedDistrict.code);
        final matchedWard = wards.firstWhere(
          (node) => _normalizeForMatch(node.name) == normalizedWard,
          orElse: () => const _LocationNode(code: '', name: ''),
        );
        if (matchedWard.code.isNotEmpty) {
          return LocationSelection(
            displayName:
                '${matchedWard.name}, ${matchedDistrict.name}, ${matchedProvince.name}',
            provinceCode: matchedProvince.code,
            districtCode: matchedDistrict.code,
            wardCode: matchedWard.code,
          );
        }
      }
    }
    await _ensureOpenApiDistrictIndex();
    final districtRefs = _openApiDistrictIndex[normalizedDistrict];
    if (districtRefs == null || districtRefs.isEmpty) return null;
    for (final districtRef in districtRefs) {
      final wards = await _ensureOpenApiWards(districtRef.code);
      final matchedWard = wards.firstWhere(
        (node) => _normalizeForMatch(node.name) == normalizedWard,
        orElse: () => const _LocationNode(code: '', name: ''),
      );
      if (matchedWard.code.isEmpty) continue;
      return LocationSelection(
        displayName:
            '${matchedWard.name}, ${districtRef.name}, ${districtRef.provinceName}',
        provinceCode: districtRef.provinceCode,
        districtCode: districtRef.code,
        wardCode: matchedWard.code,
      );
    }
    return null;
  }

  _LocationNode _nodeFromApi(Map<String, dynamic> item) {
    final code = item['code']?.toString() ?? '';
    final name = item['name']?.toString() ?? '';
    final type = item['type']?.toString() ?? '';
    final display = _formatWithType(name, type);
    return _LocationNode(code: code, name: display.trim());
  }

  static String _formatWithType(String name, String type) {
    if (name.isEmpty) return '';
    if (type.isEmpty || name.startsWith(type)) {
      return name;
    }
    return '$type $name';
  }

  static String _formatAddressPart(dynamic part) {
    if (part is Map<String, dynamic>) {
      final name = part['name']?.toString() ?? '';
      final type = part['type']?.toString() ?? '';
      return _formatWithType(name, type);
    }
    return part?.toString() ?? '';
  }

  static String _normalizeForMatch(String value) {
    final normalized = _normalize(value).trim();
    const prefixes = [
      'tinh ',
      'thanh pho ',
      'thanh pho truc thuoc trung uong ',
      'quan ',
      'huyen ',
      'thi xa ',
      'thi tran ',
      'xa ',
      'phuong ',
      'dac khu ',
      'tp ',
      'tp. ',
      'tx ',
      'q ',
      'h ',
      'p ',
    ];
    for (final prefix in prefixes) {
      if (normalized.startsWith(prefix)) {
        return normalized.substring(prefix.length).trim();
      }
    }
    return normalized;
  }

  static Map<String, dynamic>? _extractAddressBlock(
    Map<String, dynamic> record,
  ) {
    final candidates = [
      record['new'],
      record['new_block'],
      record['newBlock'],
      record['new_address'],
      record['newAddress'],
    ];
    for (final candidate in candidates) {
      if (candidate is Map<String, dynamic>) {
        return candidate;
      }
    }
    return null;
  }

  static String? _buildAddressFromNewBlock(
    Map<String, dynamic> newBlock,
  ) {
    final wardPart = _formatAddressPart(
      newBlock['ward'] ?? newBlock['new_ward'],
    );
    final districtPart = _formatAddressPart(
      newBlock['district'] ?? newBlock['new_district'],
    );
    final provincePart = _formatAddressPart(
      newBlock['province'] ?? newBlock['new_province'],
    );
    final parts = <String>[];
    if (wardPart.isNotEmpty) {
      parts.add(wardPart);
    }
    if (districtPart.isNotEmpty) {
      parts.add(districtPart);
    }
    if (provincePart.isNotEmpty) {
      parts.add(provincePart);
    }
    if (parts.isEmpty) return null;
    return parts.join(', ');
  }

