      setState(() {
        _currentList = List<_LocationNode>.from(_provinceList);
        _loading = false;
      });
      return;
    }
    setState(() {
      _loading = true;
      _loadError = null;
    });
    try {
      final data = await _fetchData('/provinces?limit=100');
      final provinces = data
          .map((item) => _nodeFromApi(item as Map<String, dynamic>))
          .where((node) => node.code.isNotEmpty)
          .toList();
      provinces.sort((a, b) => a.name.compareTo(b.name));
      _provinceByCode
        ..clear()
        ..addEntries(provinces.map((node) => MapEntry(node.code, node)));
      _provinceList
        ..clear()
        ..addAll(provinces);
      if (!mounted) return;
      setState(() {
        _currentList = provinces;
        _loading = false;
      });
    } catch (_) {
      if (!mounted) return;
