  Future<void> _loadDistricts(String provinceCode) async {
    final cached = _districtCache[provinceCode];
    if (cached != null) {
      _districtByCode
        ..clear()
        ..addEntries(cached.map((node) => MapEntry(node.code, node)));
      setState(() {
        _currentList = cached;
        _loading = false;
      });
      return;
    }
    setState(() {
      _loading = true;
      _loadError = null;
    });
    try {
      final data =
          await _fetchData('/provinces/$provinceCode/districts?limit=1000');
      final districts = data
          .map((item) => _nodeFromApi(item as Map<String, dynamic>))
          .where((node) => node.code.isNotEmpty)
          .toList();
      districts.sort((a, b) => a.name.compareTo(b.name));
      _districtByCode
        ..clear()
        ..addEntries(districts.map((node) => MapEntry(node.code, node)));
      _districtCache[provinceCode] = districts;
      if (!mounted) return;
      setState(() {
        _currentList = districts;
        _loading = false;
      });
    } catch (_) {
