  Future<void> _loadWards(String districtCode) async {
    final cached = _wardCache[districtCode];
    if (cached != null) {
      setState(() {
        _currentList = cached;
        _loading = false;
      });
      return;
    }
    setState(() {
      _loading = true;
      _loadError = null;
    });
    try {
      final data =
          await _fetchData('/districts/$districtCode/wards?limit=2000');
      final wards = data
          .map((item) => _nodeFromApi(item as Map<String, dynamic>))
          .where((node) => node.code.isNotEmpty)
          .toList();
      wards.sort((a, b) => a.name.compareTo(b.name));
      if (!mounted) return;
      setState(() {
        _currentList = wards;
        _loading = false;
      });
      _wardCache[districtCode] = wards;
    } catch (_) {
