  List<_LocationNode> _filterNodes(List<_LocationNode> items) {
    if (_query.isEmpty) return items;
    final normalizedQuery = _normalize(_query);
    return items
        .where((item) => _normalize(item.name).contains(normalizedQuery))
        .toList();
  }

  Future<LocationSelection?> _resolveMergeSelection(
    _LocationNode ward,
  ) async {
    if (_mergeApiKey.isEmpty) return null;
    final client = HttpClient();
    try {
      final uri = Uri.parse('$_apiBaseUrl/merge-history/ward/${ward.code}');
      final request = await client.getUrl(uri);
      request.headers.set('Authorization', 'Bearer $_mergeApiKey');
      request.headers.set('Accept', 'application/json');
      final response = await request.close();
      final body = await response.transform(utf8.decoder).join();
      if (response.statusCode < 200 || response.statusCode >= 300) {
        return null;
      }
      final json = jsonDecode(body) as Map<String, dynamic>;
      final data = json['data'];
      if (data is! List || data.isEmpty) return null;
      final record = data.first as Map<String, dynamic>;
      final province = _provinceByCode[_selectedProvinceCode]?.name ?? '';
      final district = _districtByCode[_selectedDistrictCode]?.name ?? '';
      final oldDisplay =
          '${ward.name}, $district, $province'.replaceAll(RegExp(r',\s+$'), '');
      final newBlock = _extractAddressBlock(record);
      final newWard = record['new_ward'] ??
          record['newWard'] ??
          newBlock?['ward'] ??
          newBlock?['new_ward'] ??
          newBlock?['newWard'];
      final newDistrict = record['new_district'] ??
          record['newDistrict'] ??
          newBlock?['district'] ??
          newBlock?['new_district'] ??
          newBlock?['newDistrict'];
      final newProvince = record['new_province'] ??
          record['newProvince'] ??
          newBlock?['province'] ??
          newBlock?['new_province'] ??
          newBlock?['newProvince'];
      final newWardDisplay = _formatAddressPart(newWard);
      final newDistrictDisplay = _formatAddressPart(newDistrict);
      var newProvinceDisplay = _formatAddressPart(newProvince);
      String? overrideProvinceDisplay;
      if (newWard is Map<String, dynamic>) {
        final newWardCode = newWard['code']?.toString();
        if (newWardCode != null) {
          overrideProvinceDisplay = _provinceOverrideByWardCode[newWardCode];
        }
      }
      overrideProvinceDisplay ??=
          _provinceOverrideByWardCode[record['new_ward_code']?.toString() ?? ''];
      if (overrideProvinceDisplay != null &&
          overrideProvinceDisplay.isNotEmpty) {
        newProvinceDisplay = overrideProvinceDisplay;
      }
      if (newProvinceDisplay.isEmpty) {
        newProvinceDisplay = province;
      }
      final parts = <String>[];
      if (newWardDisplay.isNotEmpty) {
        parts.add(newWardDisplay);
      }
      if (newDistrictDisplay.isNotEmpty) {
        parts.add(newDistrictDisplay);
      }
      if (newProvinceDisplay.isNotEmpty) {
        parts.add(newProvinceDisplay);
      }
      final newDisplay = parts.isNotEmpty
          ? parts.join(', ')
          : oldDisplay;
      return LocationSelection(
        displayName: newDisplay,
        oldDisplayName: oldDisplay,
        provinceCode: _selectedProvinceCode ?? '',
        districtCode: _selectedDistrictCode ?? '',
        wardCode: ward.code,
      );
    } catch (_) {
      return null;
    } finally {
      client.close(force: true);
    }
  }

  Future<String?> _convertAddressDisplay({
    required String provinceCode,
    required String districtCode,
    required String wardCode,
  }) async {
    if (_mergeApiKey.isEmpty) return null;
    final client = HttpClient();
    try {
      final uri = Uri.parse('$_apiBaseUrl/convert/address');
      final request = await client.postUrl(uri);
      request.headers.contentType = ContentType.json;
      request.headers.set('Authorization', 'Bearer $_mergeApiKey');
      request.headers.set('Accept', 'application/json');
      request.write(jsonEncode({
        'provinceCode': provinceCode,
        'districtCode': districtCode,
        'wardCode': wardCode,
        'streetAddress': '',
      }));
      final response = await request.close();
      final body = await response.transform(utf8.decoder).join();
      if (response.statusCode < 200 || response.statusCode >= 300) {
        return null;
      }
      if (body.isEmpty) return null;
      final json = jsonDecode(body) as Map<String, dynamic>;
      if (json['success'] == false) return null;
      final data = json['data'];
      if (data is Map<String, dynamic>) {
        final newBlock = data['new'];
        if (newBlock is Map<String, dynamic>) {
          final composed = _buildAddressFromNewBlock(newBlock);
          if (composed != null && composed.isNotEmpty) {
            return composed;
          }
          final fullAddress = newBlock['fullAddress']?.toString() ??
              newBlock['full_address']?.toString();
          if (fullAddress != null && fullAddress.isNotEmpty) {
            return fullAddress;
          }
        }
        return data['new_address']?.toString() ??
            data['newAddress']?.toString() ??
            data['new_address_line']?.toString() ??
            data['address_new']?.toString() ??
            data['full_address']?.toString();
      }
      return null;
    } catch (_) {
      return null;
    } finally {
      client.close(force: true);
    }
  }

  Future<String?> _convertTrackAsiaDisplay({
    required String addressText,
  }) async {
    if (_trackAsiaApiKey.isEmpty) return null;
    final trimmed = addressText.trim();
    if (trimmed.isEmpty) return null;
    final client = HttpClient();
    try {
      final uri = Uri.parse('$_trackAsiaBaseUrl/place/convert/json').replace(
        queryParameters: {
          'text': trimmed,
          'migrate_type': 'old_to_new',
          'key': _trackAsiaApiKey,
        },
      );
      final request = await client.getUrl(uri);
      request.headers.set('Accept', 'application/json');
      final response = await request.close();
      final body = await response.transform(utf8.decoder).join();
      if (response.statusCode < 200 || response.statusCode >= 300) {
        return null;
      }
      if (body.isEmpty) return null;
      final json = jsonDecode(body) as Map<String, dynamic>;
      if (json['status']?.toString() != 'OK') {
        return null;
      }
      final results = json['results'];
      if (results is! List || results.isEmpty) return null;
      final first = results.first;
      if (first is! Map<String, dynamic>) return null;
      final formatted = first['formatted_address']?.toString() ?? '';
      if (formatted.isEmpty) return null;
      return formatted;
    } catch (_) {
      return null;
    } finally {
      client.close(force: true);
    }
  }

  @override
  Widget build(BuildContext context) {
    final isProvinceStep = _selectedProvinceCode == null;
    final isDistrictStep =
        _selectedProvinceCode != null && _selectedDistrictCode == null;
    final filtered = _filterNodes(_currentList);

    final title = isProvinceStep
        ? 'Tỉnh/ Thành phố'
        : isDistrictStep
            ? 'Quận/ Huyện'
            : 'Phường/ Xã';

    return Scaffold(
      appBar: AppBar(
        toolbarHeight: 44,
        elevation: 0,
        backgroundColor: Colors.transparent,
        iconTheme: const IconThemeData(color: Colors.white),
        flexibleSpace: Container(
          decoration: const BoxDecoration(
            gradient: LinearGradient(
              colors: [AppColors.orange600, AppColors.rose500],
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
            ),
          ),
        ),
        title: SizedBox(
          height: 32,
          child: TextField(
            controller: _searchController,
            onChanged: (value) => setState(() => _query = value.trim()),
            textAlignVertical: TextAlignVertical.center,
            style: const TextStyle(fontSize: 13),
            decoration: InputDecoration(
              hintText: isProvinceStep
                  ? 'Tìm kiếm Tỉnh/Thành phố'
                  : isDistrictStep
                      ? 'Tìm kiếm Quận/Huyện'
                      : 'Tìm kiếm Phường/Xã',
              hintStyle: const TextStyle(fontSize: 13),
              prefixIcon: const Icon(Icons.search, size: 18),
              prefixIconConstraints:
                  const BoxConstraints(minWidth: 36, minHeight: 32),
              contentPadding: EdgeInsets.zero,
              isDense: true,
              filled: true,
              fillColor: Colors.white,
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(999),
                borderSide: BorderSide.none,
              ),
            ),
          ),
        ),
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _loadError != null
              ? Center(
                  child: Text(
                    _loadError!,
                    style: Theme.of(context)
                        .textTheme
                        .bodySmall
                        ?.copyWith(color: AppColors.gray600),
                  ),
                )
              : Stack(
                  children: [
                    ListView(
                      padding: const EdgeInsets.fromLTRB(16, 8, 16, 16),
                      children: [
                        Text(
                          title,
                          style: Theme.of(context)
                              .textTheme
                              .bodySmall
                              ?.copyWith(color: AppColors.gray600),
                        ),
                        const SizedBox(height: 8),
                        if (filtered.isEmpty)
                          Padding(
                            padding: const EdgeInsets.symmetric(vertical: 12),
                            child: Text(
                              'Khong tim thay du lieu.',
                              style: Theme.of(context)
                                  .textTheme
                                  .bodySmall
                                  ?.copyWith(color: AppColors.gray600),
                            ),
                          )
                        else
                          ..._buildPlainList(filtered),
                      ],
                    ),
                    if (_resolvingMerge)
                      Container(
                        color: Colors.white.withOpacity(0.6),
                        child: const Center(
                          child: CircularProgressIndicator(),
                        ),
                      ),
                  ],
                ),
    );
  }

  List<Widget> _buildPlainList(List<_LocationNode> items) {
    return items.map(_buildItem).toList();
  }

  Widget _buildItem(_LocationNode item) {
    return InkWell(
      onTap: () async {
        if (_selectedProvinceCode == null) {
          setState(() {
            _selectedProvinceCode = item.code;
            _query = '';
            _searchController.clear();
          });
          await _loadDistricts(item.code);
          return;
        }
        if (_selectedDistrictCode == null) {
          setState(() {
            _selectedDistrictCode = item.code;
            _query = '';
            _searchController.clear();
          });
          await _loadWards(item.code);
          return;
        }
        final province = _provinceByCode[_selectedProvinceCode]?.name ?? '';
        final district = _districtByCode[_selectedDistrictCode]?.name ?? '';
        final oldDisplay =
            '${item.name}, $district, $province'.replaceAll(RegExp(r',\s+$'), '');
        LocationSelection selection = LocationSelection(
          displayName: oldDisplay,
          provinceCode: _selectedProvinceCode ?? '',
          districtCode: _selectedDistrictCode ?? '',
          wardCode: item.code,
        );
        setState(() => _resolvingMerge = true);
        final convertedDisplay = await _convertAddressDisplay(
          provinceCode: _selectedProvinceCode ?? '',
          districtCode: _selectedDistrictCode ?? '',
          wardCode: item.code,
        );
        if (convertedDisplay != null && convertedDisplay.isNotEmpty) {
          selection = LocationSelection(
            displayName: convertedDisplay,
            oldDisplayName:
                convertedDisplay == oldDisplay ? null : oldDisplay,
            provinceCode: _selectedProvinceCode ?? '',
            districtCode: _selectedDistrictCode ?? '',
              wardCode: item.code,
            );
        } else {
          final trackAsiaDisplay = await _convertTrackAsiaDisplay(
            addressText: oldDisplay,
          );
          if (trackAsiaDisplay != null && trackAsiaDisplay.isNotEmpty) {
            selection = LocationSelection(
              displayName: trackAsiaDisplay,
              oldDisplayName:
                  trackAsiaDisplay == oldDisplay ? null : oldDisplay,
              provinceCode: _selectedProvinceCode ?? '',
              districtCode: _selectedDistrictCode ?? '',
              wardCode: item.code,
            );
          } else {
            final openApiDisplay = await _resolveOpenApiDisplay(
              wardName: item.name,
              districtName: district,
              provinceName: province,
            );
            if (openApiDisplay != null && openApiDisplay.isNotEmpty) {
              selection = LocationSelection(
                displayName: openApiDisplay,
                oldDisplayName:
                    openApiDisplay == oldDisplay ? null : oldDisplay,
                provinceCode: _selectedProvinceCode ?? '',
                districtCode: _selectedDistrictCode ?? '',
                wardCode: item.code,
              );
            } else if (_mergeApiKey.isNotEmpty) {
              final merged = await _resolveMergeSelection(item);
              if (merged != null) {
                selection = merged;
              }
            }
          }
        }
        if (mounted) {
          setState(() => _resolvingMerge = false);
        }
        if (!mounted) return;
        Navigator.pop(context, selection);
      },
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 12),
        decoration: const BoxDecoration(
          border: Border(
            bottom: BorderSide(color: AppColors.gray200),
          ),
        ),
        child: Text(
          item.name,
          style: const TextStyle(fontWeight: FontWeight.w500),
        ),
      ),
    );
  }
}

class _LocationNode {
  const _LocationNode({required this.code, required this.name});

  final String code;
  final String name;
}

class _OpenDistrictRef {
  const _OpenDistrictRef({
    required this.code,
    required this.name,
    required this.provinceCode,
    required this.provinceName,
  });

  final String code;
  final String name;
  final String provinceCode;
  final String provinceName;
}

class LocationSelection {
  const LocationSelection({
    required this.displayName,
    required this.provinceCode,
    required this.districtCode,
    required this.wardCode,
    this.oldDisplayName,
  });

  final String displayName;
  final String provinceCode;
  final String districtCode;
  final String wardCode;
  final String? oldDisplayName;
}









